function editEvent(id){const e=events.find(x=>x.id===id);if(!e)return;openModal(`<div class="eyebrow muted-eyebrow">لوحة مدير النظام</div><h2>تعديل الإعلان</h2><form class="modal-form" id="editEventForm"><label>عنوان الإعلان<input name="title" required value="${escapeHTML(e.title)}"></label><label>نوع الفعالية<select name="category">${["معارض وعروض","تقنية وابتكار","مؤتمرات ولقاءات","فعاليات ثقافية وفنية","فعاليات اجتماعية وترفيهية","رياضية","حفلات ومناسبات","ورش وتدريب"].map(c=>`<option ${e.category===c?"selected":""}>${c}</option>`).join("")}</select></label><label>الكلية<input name="college" required value="${escapeHTML(e.college||"")}"></label><label>الجهة المنظمة<input name="organizer" required value="${escapeHTML(e.organizer||"")}"></label><div class="form-two"><label>تاريخ البداية<input type="date" name="date" required value="${escapeHTML(e.date||futureDate(1))}"></label><label>تاريخ النهاية<input type="date" name="endDate" value="${escapeHTML(e.endDate||e.date||futureDate(1))}"></label></div><label>الوقت<input name="time" value="${escapeHTML(e.time||"")}" placeholder="10:00 ص – 12:00 م"></label><label>الموقع<input name="location" required value="${escapeHTML(e.location||"")}"></label><label>رابط صورة الإعلان (اختياري)<input name="imageUrl" type="url" value="${escapeHTML(/^https?:\/\//i.test(e.image||"")?e.image:"")}" placeholder="https://example.com/poster.jpg"></label><label>رفع صورة جديدة (اختياري)<input name="imageFile" type="file" accept="image/*"></label><label>الوصف<textarea name="description" required>${escapeHTML(e.description||"")}</textarea></label><button class="primary-btn full">حفظ التعديلات</button></form>`);$("editEventForm").onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),ix=events.findIndex(x=>x.id===id);if(ix<0)return;let image=String(f.get("imageUrl")||"").trim()||events[ix].image||"";if(f.get("imageUrl")){try{const parsed=new URL(image);if(!["http:","https:"].includes(parsed.protocol)){toast("استخدمي رابط صورة يبدأ بـ http أو https.");return;}}catch{toast("أدخلي رابط صورة صالحًا.");return;}}const file=f.get("imageFile");try{if(file&&file.size>0)image=await compressImage(file);}catch(err){toast(err.message);return;}if(f.get("endDate")&&f.get("endDate")<f.get("date")){toast("تاريخ النهاية يجب ألا يسبق تاريخ البداية.");return;}const updated={...events[ix],title:f.get("title"),category:f.get("category"),college:f.get("college"),organizer:f.get("organizer"),date:f.get("date"),dateLabel:formatDate(f.get("date")),endDate:f.get("endDate"),time:f.get("time"),location:f.get("location"),description:f.get("description"),image};events[ix]=updated;if(baseEvents.some(x=>x.id===id))state.eventOverrides[id]=updated;persist();closeModal();renderEvents();renderSaved();renderClubs();renderClubStrip();toast("تم حفظ تعديلات الإعلان محليًا.");};}
function confirmDeleteEvent(id){const e=events.find(x=>x.id===id);if(!e)return;if(!canDeleteEvent(e)){toast("ما عندك صلاحية حذف هذا الإعلان.");return;}const isSystemAdmin=currentRole==="admin";openModal(`<div class="eyebrow muted-eyebrow">${isSystemAdmin?"صلاحيات مدير النظام":"إدارة منشورات النادي"}</div><h2>حذف الإعلان؟</h2><p>${isSystemAdmin?"لديك صلاحية حذف أي إعلان من المنصة.":`يمكنك حذف منشورات ${escapeHTML(currentClub)} فقط.`} سيُزال «${escapeHTML(e.title)}» من الفعاليات ومنشورات النادي المرتبط به.</p><div class="detail-actions"><button class="danger-btn" id="confirmDeleteEvent">حذف الإعلان</button><button class="secondary-btn" id="cancelDeleteEvent">إلغاء</button></div>`);$("cancelDeleteEvent").onclick=closeModal;$("confirmDeleteEvent").onclick=()=>{if(!canDeleteEvent(e)){closeModal();toast("ما عندك صلاحية حذف هذا الإعلان.");return;}if(baseEvents.some(x=>x.id===id)){if(!state.deletedEventIds.includes(id))state.deletedEventIds.push(id);delete state.eventOverrides[id];}const ix=events.findIndex(x=>x.id===id);if(ix>=0)events.splice(ix,1);state.customEvents=events.filter(x=>!baseEvents.some(b=>b.id===x.id));state.favorites=state.favorites.filter(x=>x!==id);state.registered=state.registered.filter(x=>x!==id);persist();closeModal();renderEvents();renderSaved();renderClubs();renderClubStrip();toast("تم حذف الإعلان محليًا.");};}
