function compressImage(file){return new Promise((resolve,reject)=>{if(!file)return resolve("");if(!file.type.startsWith("image/"))return reject(new Error("اختاري ملف صورة صالحًا."));const reader=new FileReader();reader.onerror=()=>reject(new Error("تعذر قراءة الصورة."));reader.onload=()=>{const data=reader.result;if(file.type.includes("svg")||file.size<350000){resolve(data);return;}const img=new Image();img.onload=()=>{const max=1100,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement("canvas");canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",.76));};img.onerror=()=>resolve(data);img.src=data;};reader.readAsDataURL(file);});}
