async function hashPassword(password){try{const bytes=new TextEncoder().encode(password),hash=await crypto.subtle.digest("SHA-256",bytes);return Array.from(new Uint8Array(hash)).map(b=>b.toString(16).padStart(2,"0")).join("");}catch{return password;}}
