function renderAuth(){const isReg=authMode==="register",isReset=authMode==="reset";openModal(`<div class="auth-top"><div class="brand-mark">و</div><div class="eyebrow muted-eyebrow">أهلًا بك في وَصْل</div><h2>${isReg?"حسابك الجامعي، أقرب لك":isReset?"استعادة كلمة المرور":"نورت وَصْل من جديد"}</h2><p>${isReg?"أنشئ حسابًا لتكتشف الفعاليات وتحفظ اهتماماتك.":isReset?"أدخل بريدك الإلكتروني لاستعادة إمكانية الدخول.":"سجّل دخولك وواصل رحلتك مع مجتمع الجامعة."}</p></div><div class="auth-tabs"><button class="${authMode==="login"?"selected":""}" data-auth="login">تسجيل الدخول</button><button class="${isReg?"selected":""}" data-auth="register">إنشاء حساب</button></div>${isReg?`<form class="modal-form auth-form" id="authForm"><label>اسم المستخدم<input name="username" required maxlength="20" minlength="1" autocomplete="username" placeholder="من حرف إلى 20 حرفًا"><small class="field-help">اسم فريد من 1 إلى 20 حرفًا.</small></label><label>البريد الإلكتروني الجامعي<input name="email" type="email" required autocomplete="email" placeholder="name@university.edu.sa"></label><label>كلمة المرور<input name="password" type="password" required minlength="8" autocomplete="new-password" placeholder="8 أحرف أو أكثر"></label><label>الجامعة<select name="university" required><option value="جامعة جدة">جامعة جدة</option></select></label><label>الكلية<select name="college" required><option>الحاسبات وتقنية المعلومات</option><option>الهندسة</option><option>الأعمال</option><option>العلوم</option><option>التصاميم والفنون</option><option>الطب</option><option>كلية أخرى</option></select></label><button class="primary-btn full">إنشاء الحساب</button></form>`:isReset?`<form class="modal-form auth-form" id="authForm"><label>البريد الإلكتروني<input name="email" type="email" required autocomplete="email" placeholder="أدخل بريدك الإلكتروني"></label><button class="primary-btn full">إرسال رابط الاستعادة</button><button class="secondary-btn full" type="button" data-auth="login">العودة إلى تسجيل الدخول</button></form>`:`<form class="modal-form auth-form" id="authForm"><label>البريد الإلكتروني أو اسم المستخدم<input name="identifier" required autocomplete="username" placeholder="البريد الجامعي أو اسم المستخدم"></label><label>كلمة المرور<input name="password" type="password" required autocomplete="current-password" placeholder="أدخل كلمة المرور"></label><button class="primary-btn full">تسجيل الدخول</button><div class="auth-links"><button class="text-btn" type="button" data-auth="reset">نسيت كلمة المرور؟</button><span aria-hidden="true">·</span><button class="text-btn" type="button" id="continueAuthLater">تسجيل الدخول لاحقًا</button></div></form>`}<p class="demo-note">تنبيه: هذه نسخة واجهة محلية؛ لا تستخدمي كلمة مرورك الحقيقية. لا يوجد خادم أو تحقق جامعي في هذا الإصدار.</p>`);
  document.querySelectorAll("[data-auth]").forEach(b=>b.onclick=()=>renderAuthMode(b.dataset.auth));
  const laterButton=$("continueAuthLater");if(laterButton)laterButton.onclick=continueAsGuest;
  const form=$("authForm");if(!form)return;
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(isReg){const username=String(f.get("username")||"").trim(),email=String(f.get("email")||"").trim().toLowerCase(),password=String(f.get("password")||"");if(username.length<1||username.length>20){toast("يجب أن يتراوح اسم المستخدم بين حرف واحد و20 حرفًا");return;}if(password.length<8){toast("كلمة المرور لا تستوفي الشروط المطلوبة");return;}if(state.accounts.some(a=>String(a?.username||"").trim().toLowerCase()===username.toLowerCase())){toast("اسم المستخدم غير متاح. اختر اسمًا آخر");return;}if(state.accounts.some(a=>String(a?.email||"").trim().toLowerCase()===email)){toast("هذا البريد الإلكتروني مسجل بالفعل. جرّب تسجيل الدخول");return;}const record={username,email,passwordHash:await hashPassword(password),university:f.get("university"),college:f.get("college"),created:new Date().toISOString()};state.accounts.push(record);state.authUser=username;state.user={...state.user,displayName:username,username,email,university:record.university,college:record.college,role:"student"};currentRole="student";authGateActive=false;persist();closeModal();updateRoleUI();toast("تم إنشاء حسابك بنجاح! أهلًا بك في وَصْل");}
  else if(isReset){toast("إذا كان البريد مسجلًا، فستصلك تعليمات استعادة كلمة المرور.");renderAuthMode("login");}
  else{const identifier=String(f.get("identifier")||"").trim().toLowerCase(),password=String(f.get("password")||""),passwordHash=await hashPassword(password);const record=state.accounts.find(a=>String(a?.username||"").trim().toLowerCase()===identifier||String(a?.email||"").trim().toLowerCase()===identifier);if(!record){toast("ما لقينا حسابًا بهذا البريد أو اسم المستخدم. تأكدي من البيانات أو أنشئي حسابًا.");return;}const matches=record.passwordHash===passwordHash||record.passwordHash===password||record.password===password;if(!matches){toast("كلمة المرور غير صحيحة. تأكدي منها أو استخدمي استعادة كلمة المرور.");return;}if(record.passwordHash===password||!record.passwordHash)record.passwordHash=passwordHash;delete record.password;state.authUser=String(record.username||identifier);state.user={...state.user,displayName:record.username||identifier,username:record.username||identifier,email:record.email||identifier,university:record.university||"جامعة جدة",college:record.college||state.user.college,role:"student"};currentRole="student";authGateActive=false;persist();closeModal();updateRoleUI();toast("تم تسجيل الدخول بنجاح.");}
  };
}
function renderAuthMode(mode){authMode=mode;renderAuth();}
function openNotifications(){const clubUpdates=clubs.filter(c=>state.joinedClubs.includes(c.id)).flatMap(c=>clubEvents(c).filter(e=>!state.eventPrefs.length||state.eventPrefs.includes(e.category)).slice(0,2).map(e=>({title:`إعلان جديد من ${c.name}`,body:e.title,date:e.created||e.date})));const all=[...state.notifications,...clubUpdates].sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));openModal(`<div class="eyebrow muted-eyebrow">ابقَ على اطلاع</div><h2>التنبيهات</h2><div class="notification-list">${all.length?all.map(n=>`<article class="notification-item"><span class="notification-dot">✦</span><div><b>${escapeHTML(n.title)}</b><p>${escapeHTML(n.body)}</p><small>${escapeHTML(n.date?new Intl.DateTimeFormat("ar-SA",{dateStyle:"medium",timeStyle:"short"}).format(new Date(n.date)):"حديثًا")}</small></div></article>`).join(""):'<p class="empty-note">ما عندك تنبيهات جديدة حاليًا.</p>'}</div>`);}
function hour12To24(hour, period){let h=Number(hour)%12;if(period==="م")h+=12;return h;}
function hourOptions(selected){return Array.from({length:12},(_,i)=>i+1).map(h=>`<option value="${h}" ${Number(selected)===h?"selected":""}>${h}</option>`).join("");}
function createRoomForm(){
  if(!isSignedIn()){openAuth("login");return;}
  if(state.joinedRooms.length){toast("أنت منضم لجلسة حاليًا. اخرج منها أولًا لإنشاء جلسة جديدة.");return;}
  const now=new Date();
  const startHour=(now.getHours()%12)||12;
  const startPeriod=now.getHours()>=12?"م":"ص";
  const defaultEnd=((hour12To24(startHour,startPeriod)+2)%24);
  const endHour=(defaultEnd%12)||12;
  const endPeriod=defaultEnd>=12?"م":"ص";
  openModal(`<div class="eyebrow muted-eyebrow">اجمع الناس</div><h2>أنشئ جلسة جلسة</h2><p>حدّد وقت البداية والنهاية بالساعة فقط، من 1 إلى 12 مع ص أو م. لا تحتاج إلى إدخال تاريخ.</p>
  <form class="modal-form" id="roomForm">
    <label>اسم الجلسة<input name="title" required maxlength="80" placeholder="مثال: مذاكرة قبل الاختبار"></label>
    <label>نوع النشاط<select name="kind"><option>مذاكرة</option><option>ألعاب</option><option>رياضة</option><option>جلسة</option></select></label>
    <label>الموقع<input name="location" required placeholder="مثال: مكتبة الجامعة"></label>
    <label>الحد الأقصى للمشاركين<select name="max"><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option><option>8</option><option>10</option><option selected>12</option></select><small class="field-help">يمكن أن تضم الجلسة حتى 12 مشاركًا.</small></label>
    <div class="room-time-selects">
      <div class="room-time-field"><span class="room-time-title">وقت البدء</span><div class="room-time-controls"><label>الساعة<select name="startHour" required>${hourOptions(startHour)}</select></label><label>الفترة<select name="startPeriod" required><option value="ص" ${startPeriod==="ص"?"selected":""}>صباحًا (ص)</option><option value="م" ${startPeriod==="م"?"selected":""}>مساءً (م)</option></select></label></div></div>
      <div class="room-time-field"><span class="room-time-title">وقت الانتهاء</span><div class="room-time-controls"><label>الساعة<select name="endHour" required>${hourOptions(endHour)}</select></label><label>الفترة<select name="endPeriod" required><option value="ص" ${endPeriod==="ص"?"selected":""}>صباحًا (ص)</option><option value="م" ${endPeriod==="م"?"selected":""}>مساءً (م)</option></select></label></div></div>
    </div>
    <label>وصف مختصر<textarea name="desc" maxlength="500" placeholder="وش مخططين تسوون؟"></textarea></label>
    <button class="primary-btn full">إنشاء الجلسة</button>
  </form>`);
  $("roomForm").onsubmit=e=>{
    e.preventDefault();
    const f=new FormData(e.target);
    const startHour=hour12To24(f.get("startHour"),f.get("startPeriod"));
    const endHour=hour12To24(f.get("endHour"),f.get("endPeriod"));
    const duration=(endHour-startHour+24)%24;
    if(duration===0){toast("اختاري وقت انتهاء مختلفًا عن وقت البدء.");return;}
    const startTime=`${f.get("startHour")}:00 ${f.get("startPeriod")}`;
    const endTime=`${f.get("endHour")}:00 ${f.get("endPeriod")}`;
    if(state.joinedRooms.length){toast("اخرج من الجلسة الحالية أولًا لإنشاء جلسة جديدة.");return;}
    const kind=f.get("kind"),id="r"+Date.now();
    rooms.unshift({id,title:String(f.get("title")).trim(),kind,icon:{"مذاكرة":"▤","ألعاب":"♠","رياضة":"↗","جلسة":"✦"}[kind],color:"#8b6bff30",host:state.user.displayName||"مستخدم وصل",ownerUsername:currentIdentity(),createdBy:currentIdentity(),location:String(f.get("location")).trim(),startTime,endTime,startHour,endHour,joined:1,max:Math.min(12,Number(f.get("max"))||12),desc:String(f.get("desc")||"").trim()||"جلسة جديدة للطلاب."});
    state.joinedRooms=[id];
    persist();closeModal();renderRooms();addNotification("تم إنشاء جلسة",`أنشأت جلسة ${f.get("title")}.`);toast("تم إنشاء الجلسة محليًا");goPage("rooms");
  };
}
function saveSettings(){state.eventPrefs=[...document.querySelectorAll('#eventPreferences input:checked')].map(x=>x.value);state.roomPrefs=[...document.querySelectorAll('#roomPreferences input:checked')].map(x=>x.value);state.privacyEnabled=$("privacyToggle")?$("privacyToggle").checked:true;const newEmail=$("settingsEmail").value.trim().toLowerCase();if(newEmail&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(newEmail)){toast("أدخل بريدًا إلكترونيًا صالحًا.");return;}const username=state.authUser||state.user.username;const account=state.accounts.find(a=>a.username===username);if(newEmail&&state.accounts.some(a=>a.email===newEmail&&a.username!==username)){toast("هذا البريد الإلكتروني مسجل بالفعل. جرّب بريدًا آخر.");return;}state.user.email=newEmail||state.user.email;if(account&&newEmail)account.email=newEmail;persist();const pw=$("settingsPassword").value;if(pw){if(pw.length<8){toast("كلمة المرور لا تستوفي الشروط المطلوبة");return;}if(!account){toast("تم حفظ بقية الإعدادات. سجّل الدخول بحساب تجريبي لتغيير كلمة المرور.");return;}hashPassword(pw).then(h=>{account.passwordHash=h;$("settingsPassword").value="";persist();toast("تم حفظ الإعدادات وكلمة المرور التجريبية.");});}else toast("تم حفظ الإعدادات والتفضيلات.");}
